                    - (anti_reverse_g1[0] * geometric_anti_product_g2[0])
                    - (anti_reverse_g1[1] * geometric_anti_product_g2[1])
                    - (anti_reverse_g1[2] * geometric_anti_product_g2[2])
                    - (anti_reverse_g1[3] * geometric_anti_product_g2[3])
                    - (anti_reverse_g2[0] * geometric_anti_product_g1[0])
                    - (anti_reverse_g2[1] * geometric_anti_product_g1[1])
