impl AntiSandwich<Plane> for AntiFlector {
    type Output = Plane;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32       11       20        0
    //    simd4        7        8        0
    // Totals...
    // yes simd       18       28        0
    //  no simd       39       52        0
    fn anti_sandwich(self, other: Plane) -> Self::Output {
        use crate::elements::*;
        let geometric_anti_product_g0 = Simd32x4::from([
            -(self[e321] * other[e4235]) - (self[e2] * other[e4125]),
            -(self[e321] * other[e4315]) - (self[e3] * other[e4235]),
            -(self[e321] * other[e4125]) - (self[e1] * other[e4315]),
            (self[e2] * other[e4315]) + (self[e3] * other[e4125]),
        ]) + (self.group1().zxyx() * other.group0().yzxx());
        let geometric_anti_product_g1 = Simd32x4::from([
            (self[e1] * other[e3215]) + (self[e5] * other[e4235]),
            (self[e2] * other[e3215]) + (self[e5] * other[e4315]),
            (self[e3] * other[e3215]) + (self[e5] * other[e4125]),
            -(self[e315] * other[e4315]) - (self[e125] * other[e4125]),
        ]) + (self.group0().yzxw() * other.group0().zxyw())
            - (self.group0().zxyx() * other.group0().yzxx());
        let anti_reverse_g0 = self.group0() * Simd32x4::from(-1.0);
        return Plane::from_groups(
            // e4235, e4315, e4125, e3215
            (self.group1().yzxx() * geometric_anti_product_g0.zxy().with_w(geometric_anti_product_g1[0]))
                + Simd32x3::from(0.0).with_w(
                    (geometric_anti_product_g0[3] * self[e5]) + (geometric_anti_product_g1[1] * self[e2]) + (geometric_anti_product_g1[2] * self[e3])
                        - (anti_reverse_g0[3] * geometric_anti_product_g1[3]),
                )
                - (anti_reverse_g0.wwwx() * geometric_anti_product_g0.xyzx())
                - (geometric_anti_product_g0.ywwz() * self.group1().zyz().with_w(anti_reverse_g0[2]))
                - (geometric_anti_product_g0.wzxy() * self.group1().xxy().with_w(anti_reverse_g0[1])),
        );
    }
}
